#!/bin/bash
# Uninstall script for Mozilla Thunderbird
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Mozilla Thunderbird..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Mozilla Thunderbird if running..."
pkill -f "Mozilla Thunderbird" 2>/dev/null || true

# Kill application with bundle ID org.mozilla.thunderbird if running
echo "Stopping application with bundle ID org.mozilla.thunderbird if running..."
killall -9 "org.mozilla.thunderbird" 2>/dev/null || true

# Remove /Applications/Thunderbird.app
echo "Removing /Applications/Thunderbird.app..."
if [ -d "/Applications/Thunderbird.app" ]; then
    rm -rf "/Applications/Thunderbird.app" 2>/dev/null || true
elif [ -f "/Applications/Thunderbird.app" ]; then
    rm -f "/Applications/Thunderbird.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.thunderbird*.sfl*
echo "Removing $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.thunderbird*.sfl*..."
if [ -d "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.thunderbird*.sfl*" ]; then
    rm -rf "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.thunderbird*.sfl*" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.thunderbird*.sfl*" ]; then
    rm -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/org.mozilla.thunderbird*.sfl*" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Thunderbird
echo "Removing $HOME/Library/Application Support/Thunderbird..."
if [ -d "$HOME/Library/Application Support/Thunderbird" ]; then
    rm -rf "$HOME/Library/Application Support/Thunderbird" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Thunderbird" ]; then
    rm -f "$HOME/Library/Application Support/Thunderbird" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/Mozilla/updates/Applications/Thunderbird*
echo "Removing $HOME/Library/Caches/Mozilla/updates/Applications/Thunderbird*..."
if [ -d "$HOME/Library/Caches/Mozilla/updates/Applications/Thunderbird*" ]; then
    rm -rf "$HOME/Library/Caches/Mozilla/updates/Applications/Thunderbird*" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/Mozilla/updates/Applications/Thunderbird*" ]; then
    rm -f "$HOME/Library/Caches/Mozilla/updates/Applications/Thunderbird*" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/Thunderbird
echo "Removing $HOME/Library/Caches/Thunderbird..."
if [ -d "$HOME/Library/Caches/Thunderbird" ]; then
    rm -rf "$HOME/Library/Caches/Thunderbird" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/Thunderbird" ]; then
    rm -f "$HOME/Library/Caches/Thunderbird" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/org.mozilla.thunderbird*.plist
echo "Removing $HOME/Library/Preferences/org.mozilla.thunderbird*.plist..."
if [ -d "$HOME/Library/Preferences/org.mozilla.thunderbird*.plist" ]; then
    rm -rf "$HOME/Library/Preferences/org.mozilla.thunderbird*.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/org.mozilla.thunderbird*.plist" ]; then
    rm -f "$HOME/Library/Preferences/org.mozilla.thunderbird*.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/org.mozilla.thunderbird*.savedState
echo "Removing $HOME/Library/Saved Application State/org.mozilla.thunderbird*.savedState..."
if [ -d "$HOME/Library/Saved Application State/org.mozilla.thunderbird*.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/org.mozilla.thunderbird*.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/org.mozilla.thunderbird*.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/org.mozilla.thunderbird*.savedState" 2>/dev/null || true
fi

# Remove $HOME/Library/Thunderbird
echo "Removing $HOME/Library/Thunderbird..."
if [ -d "$HOME/Library/Thunderbird" ]; then
    rm -rf "$HOME/Library/Thunderbird" 2>/dev/null || true
elif [ -f "$HOME/Library/Thunderbird" ]; then
    rm -f "$HOME/Library/Thunderbird" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/Mozilla
echo "Removing $HOME/Library/Caches/Mozilla..."
if [ -d "$HOME/Library/Caches/Mozilla" ]; then
    rm -rf "$HOME/Library/Caches/Mozilla" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/Mozilla" ]; then
    rm -f "$HOME/Library/Caches/Mozilla" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
